DECLARE @FileName_Prefix VARCHAR(200)=@0; 
DECLARE @Market_Name VARCHAR(200)=@1; 

SELECT @FileName_Prefix+ 'Medical' +'_'+ @Market_Name+'_'+
replace(replace(replace(convert(varchar(19), getdate(), 126),'-',''),'T','_'),':','')+'.txt'
as FileName,
@FileName_Prefix+ 'Diag_Proc_Codes' +'_'+ @Market_Name+'_'+
replace(replace(replace(convert(varchar(19), getdate(), 126),'-',''),'T','_'),':','')+'.txt'
as FileName_Diag_Proc_Codes

